        static void AddCylinder(Surface surface, Vector center, Vector normal, int divs, double radius, double height, Color color)
        {
            AddFrustum(surface, center, normal, divs, radius, radius, height, true, color);
        }

        static void AddFrustum(Surface surface, Vector center, Vector normal, int divs, double radiusTop, double radiusBottom, double height, bool endcaps, Color color)
        {
            Vector axis = normal.UnitVector();
            Vector reference = Math.Abs(axis.Z) < 0.9 ? new Vector(0, 0, 1) : new Vector(0, 1, 0);
            Vector u = (reference - reference.ProjectOnto(axis)).UnitVector();
            Vector v = new(
                axis.Y * u.Z - axis.Z * u.Y,
                axis.Z * u.X - axis.X * u.Z,
                axis.X * u.Y - axis.Y * u.X
            );

            Vector halfHeight = axis * (height / 2.0);
            Vector topCenter = center + halfHeight;
            Vector bottomCenter = center - halfHeight;
            double delta = 2 * Math.PI / divs;

            for (int i = 0; i < divs; i++)
            {
                double a1 = i * delta;
                double a2 = (i + 1) * delta;
                Vector radial1 = Math.Cos(a1) * u + Math.Sin(a1) * v;
                Vector radial2 = Math.Cos(a2) * u + Math.Sin(a2) * v;

                Vector bottom1 = bottomCenter + radiusBottom * radial1;
                Vector bottom2 = bottomCenter + radiusBottom * radial2;
                Vector top1 = topCenter + radiusTop * radial1;
                Vector top2 = topCenter + radiusTop * radial2;

                surface.AddQuad(bottom1, bottom2, top2, top1, color);
                if (endcaps)
                {
                    surface.AddTriangle(new Triangle(topCenter, top1, top2, color));
                    surface.AddTriangle(new Triangle(bottomCenter, bottom2, bottom1, color));
                }
            }
        }

        static void AddImage(Surface surface, string image, Vector corner, double width, int cells, double zRot)
        {
            double cellWidth = width / cells;
            double zRotation = zRot * Math.PI / 180.0;

            for (int y = 0; y < cells; y++)
            {
                for (int x = 0; x < cells; x++)
                {
                    int hexIndex = ((cells - 1 - y) * cells + x) * 12;
                    (byte r1, byte g1, byte b1) = RGBFromHex(image.Substring(hexIndex, 6));
                    (byte r2, byte g2, byte b2) = RGBFromHex(image.Substring(hexIndex + 6, 6));
                    Color color1 = Color.FromRgb(r1, g1, b1);
                    Color color2 = Color.FromRgb(r2, g2, b2);

                    double half = cellWidth / 2.0;
                    Vector centerLocal = new((x + 0.5) * cellWidth, 0, (y + 0.5) * cellWidth);

                    Vector p00 = corner + centerLocal + RotateAroundZ(new Vector(-half, 0, -half), zRotation);
                    Vector p01 = corner + centerLocal + RotateAroundZ(new Vector(-half, 0, half), zRotation);
                    Vector p11 = corner + centerLocal + RotateAroundZ(new Vector(half, 0, half), zRotation);
                    Vector p10 = corner + centerLocal + RotateAroundZ(new Vector(half, 0, -half), zRotation);

                    surface.AddTriangle(new Triangle(p00, p01, p11, color1));
                    surface.AddTriangle(new Triangle(p00, p10, p11, color2));
                }
            }
        }

        static Vector RotateAroundZ(Vector point, double radians)
        {
            double cos = Math.Cos(radians);
            double sin = Math.Sin(radians);

            return new Vector(
                point.X * cos - point.Y * sin,
                point.X * sin + point.Y * cos,
                point.Z
            );
        }

        static (byte, byte, byte) RGBFromHex(string hex)
        {
            byte r = Convert.ToByte(hex[..2], 16);
            byte g = Convert.ToByte(hex[2..4], 16);
            byte b = Convert.ToByte(hex[4..], 16);
            return (r, g, b);
        }

